test('inherited lawn hooks remain single-pass after realistic material cloning',async()=>{
  const f=lawnFixture(),detail=new CinematicTerrain(f.scene);await Promise.resolve();
  const inherited=f.material.onBeforeCompile;
  const clone={name:'Park lawn',onBeforeCompile:(shader:Parameters<T.Material['onBeforeCompile']>[0],renderer:T.WebGLRenderer)=>{inherited(shader,renderer);shader.fragmentShader+='\n// original skin retained';},customProgramCacheKey:()=>f.material.customProgramCacheKey()+'|skin',needsUpdate:false} as unknown as T.Material;
  const object={isMesh:true,material:clone} as unknown as T.Object3D;
  const root={traverse:(visit:(o:T.Object3D)=>void)=>visit(object)} as unknown as T.Object3D;
  for(const added of f.listeners)added({child:root});await Promise.resolve();
  const shader=f.shader();clone.onBeforeCompile(shader,{} as T.WebGLRenderer);
  for(const variable of ['belleLawnFootprint','belleLawnResolved','belleLawnGrain','belleLawnPatch'])assert.equal((shader.fragmentShader.match(new RegExp('float '+variable+'=','g'))||[]).length,1);
  assert.match(shader.fragmentShader,/original skin retained/);assert.equal(f.visits(),1);
  detail.dispose();const restored=f.shader();clone.onBeforeCompile(restored,{} as T.WebGLRenderer);
  assert.doesNotMatch(restored.fragmentShader,/float belleLawnFootprint=/);assert.match(restored.fragmentShader,/original skin retained/);
});

