 assert.match(source,/recordRequestFailure\(evidence,request,phase\)/);
 assert.doesNotMatch(source,/errorText!=='net::ERR_ABORTED'/);
 assert.match(source,/evidence.passed=evidence.functionalPassed&&!evidence.failure&&evidence.errors.length===0&&evidence.failedRequests.length===0/);
