/* Only camera controls own input; the transparent camera section is not a
   flight control. Preserve photo-mode and recording actions. */
#camera-capture{pointer-events:none}
#camera-capture>button,#camera-capture .capture-panel:not([hidden]),#camera-capture .hero-clip-bar :is(button,a,input,select){pointer-events:auto}

/* Compact openings flow and scroll instead of overlapping the native flyover,
   activity and ride-selection controls. The real island remains behind them. */
@media(max-width:760px),(max-height:520px){
 #welcome.startup{overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;padding:max(16px,env(safe-area-inset-top)) max(18px,env(safe-area-inset-right)) max(20px,env(safe-area-inset-bottom)) max(18px,env(safe-area-inset-left));scroll-padding-block:16px}
 #welcome.startup :is(.cinema-top,.cinema-title,.cinema-location,.cinema-bottom){position:relative;inset:auto;width:100%;max-width:760px;margin-inline:auto;box-sizing:border-box}
 #welcome.startup .cinema-top{flex-wrap:wrap;gap:12px;margin-bottom:28px}
 #welcome.startup .cinema-tools{margin-left:auto;gap:8px;flex-wrap:wrap}
 #welcome.startup .cinema-title{animation:none;transform:none;margin-bottom:28px}
 #welcome.startup .cinema-ride-picker,#welcome.startup .cinema-ride-picker[open]{position:relative;inset:auto;width:100%;max-width:100%;margin-top:20px}
 #welcome.startup .cinema-ride-picker>summary{min-height:44px;box-sizing:border-box}
 #welcome.startup .cinema-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:stretch;gap:8px 12px;margin-top:16px;max-width:none}
 #welcome.startup .cinema-actions button{min-width:44px;min-height:44px;width:auto;max-width:100%;white-space:normal;box-sizing:border-box}
 #welcome.startup .cinema-actions #start{grid-column:1/-1;width:100%}
 #welcome.startup .cinema-location{display:flex;align-items:flex-start;gap:8px;margin-bottom:20px}
 #welcome.startup .cinema-bottom{margin-bottom:4px}
 #welcome.startup .startup-controls-panel{position:fixed;left:max(12px,env(safe-area-inset-left));right:max(12px,env(safe-area-inset-right));top:max(12px,env(safe-area-inset-top));bottom:auto;max-width:420px;max-height:calc(100dvh - 24px);overflow:auto;box-sizing:border-box;margin-inline:auto}
}
